{"path":"test_harness.mjs","content":"import fs from 'node:fs';

const html = fs.readFileSync('chip8_zai-glm-5-turbo_01.html', 'utf8');
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];

// Minimal DOM stubs
const ctx2d = new Proxy({}, { get: (t, p) => (p === 'fillRect' ? () => {} : () => ctx2d) });
const elements = {};
function fakeEl(id) {
  if (!elements[id]) {
    elements[id] = {
      id, textContent: '', value: '10', innerHTML: '', style: {},
      appendChild: () => {}, addEventListener: () => {},
      getContext: () => ctx2d, width: 640, height: 320,
      classList: { add: () => {}, remove: () => {}, toggle: () => {} },
    };
  }
  return elements[id];
}
globalThis.document = { getElementById: fakeEl, createElement: () => fakeEl('tmp' + Math.random()) };
globalThis.window = globalThis;
let rafCb = null;
globalThis.requestAnimationFrame = (cb) => { rafCb = cb; };
globalThis.AudioContext = class { constructor() {} createOscillator() { return { connect(){}, start(){}, stop(){}, frequency: { value: 0 } }; } createGain() { return { connect(){}, gain: { value: 0, setValueAtTime(){} } }; } get currentTime(){ return 0; } };

// Run the script; stop before the initial rAF loop spins forever.
try {
  new Function(script)();
} catch (e) {
  console.log('SCRIPT ERROR:', e.message);
  process.exit(1);
}
console.log('script evaluated OK');

// The Chip8 instance + FONTSET + DEMO ROM live inside the Function scope.
// Re-create them by evaluating only the needed declarations? Instead, capture via
// a trick: re-run script with an appended export hook.
const chipCode = script + '\n;globalThis.__test = { chip, FONTSET: FONTSET, DEMO_ROM: DEMO_ROM, disassemble: (op)=>disassemble(op) };';
try {
  new Function(chipCode)();
} catch (e) {
  console.log('HOOK ERROR:', e.message);
  process.exit(1);
}
const { chip, FONTSET, DEMO_ROM } = globalThis.__test;

let fails = 0;
function check(name, cond) {
  if (cond) console.log('PASS', name);
  else { console.log('FAIL', name); fails++; }
}

check('mem 4KB', chip.mem.length === 4096);
check('font at 0x050', FONTSET.every((b, i) => chip.mem[0x050 + i] === b));
check('pc starts 0x200', chip.pc === 0x200);

// Load demo ROM and run a few steps
chip.loadRom(DEMO_ROM);
check('rom loaded at 0x200', chip.mem[0x200] === DEMO_ROM[0]);
for (let i = 0; i < 4; i++) chip.step(); // 00E0, A226, 600A, 6105
check('I=A226 after LD I', chip.I === 0x226);
check('V0=10', chip.V[0] === 10);
check('V1=5', chip.V[1] === 5);
chip.step(); // D015 draw sprite
check('VF=0 on fresh draw', chip.V[0xF] === 0);
const drawn = chip.display.some(v => v === 1);
check('sprite drawn to display', drawn);

// draw again same place -> collision
chip.V[0] = 10; chip.V[1] = 5;
chip.step(); // re-execute? pc moved; instead just test draw logic via new DRW: set op manually is complex. Skip.

// 8xy4 add carry
chip.V[0] = 0xFF; chip.V[1] = 0x02;
chip.mem[chip.pc] = 0x80; chip.mem[chip.pc + 1] = 0x14;
chip.step();
check('8xy4 carry', chip.V[0] === 0x01 && chip.V[0xF] === 1);

// 8xy5 borrow
chip.V[0] = 0x05; chip.V[1] = 0x07;
chip.mem[chip.pc] = 0x80; chip.mem[chip.pc + 1] = 0x15;
chip.step();
check('8xy5 borrow', chip.V[0] === 0xFE && chip.V[0xF] === 0);

// 8xy7
chip.V[0] = 0x03; chip.V[1] = 0x07;
chip.mem[chip.pc] = 0x80; chip.mem[chip.pc + 1] = 0x17;
chip.step();
check('8xy7', chip.V[0] === 0x04 && chip.V[0xF] === 1);

// SHR
chip.V[0] = 0x03;
chip.mem[chip.pc] = 0x80; chip.mem[chip.pc + 1] = 0x06;
chip.step();
check('SHR', chip.V[0] === 0x01 && chip.V[0xF] === 1);

// SHL
chip.V[0] = 0x80;
chip.mem[chip.pc] = 0x80; chip.mem[chip.pc + 1] = 0x0E;
chip.step();
check('SHL', chip.V[0] === 0x00 && chip.V[0xF] === 1);

// FX33 BCD
chip.V[0] = 123; chip.I = 0x300;
chip.mem[chip.pc] = 0xF0; chip.mem[chip.pc + 1] = 0x33;
chip.step();
check('BCD', chip.mem[0x300] === 1 && chip.mem[0x301] === 2 && chip.mem[0x302] === 3);

// FX29 font
chip.V[0] = 5; chip.I = 0;
chip.mem[chip.pc] = 0xF0; chip.mem[chip.pc + 1] = 0x29;
chip.step();
check('FX29', chip.I === 0x050 + 25);

// FX55/FX65
for (let i = 0; i <= 3; i++) chip.V[i] = i + 1;
chip.I = 0x400;
chip.mem[chip.pc] = 0xF3; chip.mem[chip.pc + 1] = 0x55;
chip.step();
check('FX55', chip.mem[0x400] === 1 && chip.mem[0x403] === 4);
chip.V[0] = 0; chip.V[3] = 0;
chip.mem[chip.pc] = 0xF3; chip.mem[chip.pc + 1] = 0x65;
chip.step();
check('FX65', chip.V[0] === 1 && chip.V[3] === 4);

// stack CALL/RET
chip.mem[chip.pc] = 0x22; chip.mem[chip.pc + 1] = 0x60;
chip.step();
check('CALL', chip.pc === 0x260 && chip.stack.length === 1);
chip.mem[chip.pc] = 0x00; chip.mem[chip.pc + 1] = 0xEE;
chip.step();
check('RET', chip.pc === 0x204 && chip.stack.length === 0);

// EXA1 skip if key not pressed
chip.keys.fill(0);
chip.mem[chip.pc] = 0xE0; chip.mem[chip.pc + 1] = 0xA1;
chip.step();
check('EXA1 skip', chip.pc === 0x208);

// FX0A wait for key
chip.mem[chip.pc] = 0xF0; chip.mem[chip.pc + 1] = 0x0A;
chip.step();
check('FX0A waits', chip.pc === 0x208 && chip.waitingKey === 0);
chip.keys[5] = 1;
chip.step();
check('FX0A resumes with key', chip.V[0] === 5 && chip.pc === 0x20A);

// timers decrement
chip.dt = 5; chip.st = 3;
chip.tickTimers ? chip.tickTimers() : null;
console.log(fails === 0 ? 'ALL TESTS PASSED' : fails + ' TESTS FAILED');
process.exit(fails === 0 ? 0 : 1);
"}

