const btnPause = document.getElementById("btnPause");
const btnStep = document.getElementById("btnStep");
const btnReset = document.getElementById("btnReset");
const btnDemo = document.getElementById("btnDemo");
const speedSlider = document.getElementById("speed");
const speedVal = document.getElementById("speedVal");
const romFile = document.getElementById("romFile");

speedSlider.addEventListener("input", () => speedVal.textContent = speedSlider.value);

btnRun.addEventListener("click", () => running = true);
btnPause.addEventListener("click", () => running = false);
btnStep.addEventListener("click", () => { running = false; chip.step(); render(); updateDebug(); });
btnReset.addEventListener("click", () => {
  running = false;
  chip.mem.fill(0);
  chip.mem.set(FONTSET, 0x050);
  chip.loadRom(currentRom);
  chip.reset();
  chip.mem.fill(0);
  chip.mem.set(FONTSET, 0x050);
  chip.loadRom(currentRom);
  beep(false);
  render(); updateDebug();
});
btnDemo.addEventListener("click", () => {
  currentRom = DEMO_ROM.slice();
  running = false;
  chip.reset();
  chip.loadRom(currentRom);
  render(); updateDebug();
});
romFile.addEventListener("change", (e) => {
  const f = e.target.files[0];
  if (!f) return;
  const r = new FileReader();
  r.onload = () => {
    currentRom = new Uint8Array(r.result);
    running = false;
    chip.reset();
    chip.loadRom(currentRom);
    render(); updateDebug();
  };
  r.readAsArrayBuffer(f);
});

